int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config config = {0};
    int result = -EINVAL;

    if (!sb || !flags || !data) {
        return -EINVAL;
    }

    if (parse_shmem_options(data, &config) < 0) {
        return -EINVAL;
    }

    spin_lock(&sb->s_lock);

    if (sb->s_inodes_used > config.max_inodes || sb->s_blocks_used > config.max_blocks) {
        spin_unlock(&sb->s_lock);
        return -ENOSPC;
    }

    sb->s_max_inodes = config.max_inodes;
    sb->s_max_blocks = config.max_blocks;
    sb->s_free_inodes = sb->s_max_inodes - sb->s_inodes_used;

    if (config.memory_policy) {
        result = configure_memory_policy(sb, config.memory_policy);
        if (result < 0) {
            spin_unlock(&sb->s_lock);
            return result;
        }
    }

    *flags |= MS_REMOUNT;
    result = 0;

    spin_unlock(&sb->s_lock);
    return result;
}
